package org.jsoup.helper;

import org.jsoup.Connection;
import org.junit.Test;
import static org.junit.Assert.*;

import java.net.URL;
import java.net.MalformedURLException;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void UrlBuilderConstructorValidUrlTest() throws MalformedURLException {
        URL validUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(validUrl);
        assertNotNull(urlBuilder);
    }

    @Test(expected = MalformedURLException.class)
    public void UrlBuilderConstructorInvalidUrlTest() throws MalformedURLException {
        URL invalidUrl = new URL("");
        UrlBuilder urlBuilder = new UrlBuilder(invalidUrl);
    }

    @Test
    public void buildValidUrlTest() throws MalformedURLException {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL outputUrl = urlBuilder.build();
        assertEquals(inputUrl, outputUrl);
    }

    @Test(expected = RuntimeException.class)
    public void buildInvalidUrlTest() throws MalformedURLException {
        URL inputUrl = new URL("");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.build();
    }

    @Test
    public void appendKeyValValidKeyValTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal validKeyVal = Connection.KeyVal.create("foo", "bar");
        urlBuilder.appendKeyVal(validKeyVal);
        assertEquals("http://example.com?foo=bar", urlBuilder.build().toString());
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValInvalidKeyValTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal invalidKeyVal = Connection.KeyVal.create("", "");
        urlBuilder.appendKeyVal(invalidKeyVal);
    }
}
